<?php
declare(strict_types=1);
namespace Nexus\Application\Inventario;
use Nexus\Domain\Inventario\InventarioRepository;use Nexus\Shared\DomainException;
final class InventarioService
{
    private InventarioRepository $repo;public function __construct(InventarioRepository $r){$this->repo=$r;}
    public function equipos():array{return array_map(function($f){return ['id'=>(string)$f['id_equipo'],'nombre'=>$f['nombre_equipo'],'tipo'=>$f['categoria_equipo']?:'otro','tipoEtiqueta'=>$f['categoria_equipo']?:'Otro','icono'=>'package','seccionId'=>(string)$f['id_ubicacion'],'seccion'=>$f['seccion_inventario'],'fechaAlta'=>$f['fecha_agregado'],'actualizado'=>'hoy','estaActivo'=>(int)$f['esta_activo']===1,'estado'=>$f['estado_equipo']==='Baja'?'Baja':($f['estado_equipo']==='Mantenimiento'?'Mantenimiento':'Activo'),'observaciones'=>$f['descripcion']??'','marca'=>$f['marca_equipo']??'','cantidad'=>(int)$f['cantidad_del_equipo'],'cantidadDisponible'=>(int)($f['cantidad_disponible']??$f['cantidad_del_equipo'])];},$this->repo->listarEquipos());}
    public function altaEquipo(array $d):int{$this->validarEquipo($d,false);if(!$this->repo->ubicacionExiste($d['seccionId']))throw new DomainException('No existe la seccion indicada.',404);$d['activo']=$d['estado']==='Baja'?0:1;$d['estadoBase']=$d['estado']==='Mantenimiento'?'Mantenimiento':($d['estado']==='Baja'?'Baja':'Disponible');return $this->repo->crearEquipo($d);}
    public function editarEquipo(int $id,array $d):void{$this->validarEquipo($d,true);if(!in_array($d['estado'],['Disponible','Mantenimiento'],true))throw new DomainException('El estado del equipo no es valido.');if(!$this->repo->ubicacionExiste($d['seccionId'],true))throw new DomainException('No existe la seccion activa indicada.',404);if(!$this->repo->editarEquipo($id,$d))throw new DomainException('No existe el equipo activo indicado.',404);}
    public function trasladarEquipo(int $id,int $destino):array{if(!$this->repo->ubicacionExiste($destino))throw new DomainException('No existe la seccion indicada.',404);$r=$this->repo->trasladarEquipo($id,$destino);if($r===null)throw new DomainException('No existe el equipo indicado.',404);return ['ok'=>true,'sinCambios'=>$r===false];}
    public function bajaEquipo(int $id):array{$r=$this->repo->bajaEquipo($id);if($r===null)throw new DomainException('No existe el equipo indicado.',404);return ['ok'=>true,'sinCambios'=>$r===false];}
    public function ubicaciones():array{$this->exigirEsquema();return array_map(fn($f)=>['id'=>(string)$f['id_ubicacion'],'nombre'=>$f['seccion_inventario'],'icono'=>'building-2','actualizado'=>'hoy','cantidadEquipos'=>(int)$f['cantidad_equipos']],$this->repo->listarUbicaciones());}
    public function altaUbicacion(string $n):int{$this->exigirEsquema();if($n==='')throw new DomainException('El nombre de la ubicacion es obligatorio.');return $this->repo->crearUbicacion($n);}
    public function renombrarUbicacion(int $id,string $n):void{$this->exigirEsquema();if($n==='')throw new DomainException('El nombre de la ubicacion es obligatorio.');if(!$this->repo->renombrarUbicacion($id,$n))throw new DomainException('No existe la seccion activa o no hubo cambios.',404);}
    public function bajaUbicacion(int $id,?int $destino):array{$this->exigirEsquema();if($destino===$id)throw new DomainException('La seccion destino debe ser distinta a la seccion eliminada.');$r=$this->repo->bajaUbicacion($id,$destino);if($r===null)throw new DomainException('No existe la ubicacion indicada.',404);return ['ok'=>true,'sinCambios'=>!empty($r['sinCambios']),'equiposTrasladados'=>$r['cantidad']??0,'seccionDestinoId'=>isset($r['destino'])?(string)$r['destino']:''];}
    private function exigirEsquema():void{if(!$this->repo->esquemaUbicacionesActualizado())throw new DomainException('La base de datos no esta actualizada. Importa database.sql.',500);}
    private function validarEquipo(array $d,bool $edicion):void{if($d['nombre']===''||$d['tipo']==='')throw new DomainException('Nombre y categoria son obligatorios.');if(!$edicion&&(!is_int($d['cantidad'])||$d['cantidad']<1))throw new DomainException('La cantidad del equipo debe ser un entero positivo.');}
}
